use verus::prelude::*;

/// Returns the default value based on the coefficient grid `c`.
/// If `c` is exactly 1×1, returns that sole coefficient, otherwise returns 0.0.
///
/// # Panics
/// - If `c` is empty.
/// - If any row of `c` is empty.
#[requires(c.len() > 0)]
#[requires(forall(|i: usize| i < c.len() ==> c[i].len() > 0))]
#[ensures(
    result == if c.len() == 1 && c[0].len() == 1 {
        c[0][0]
    } else {
        0.0
    }
)]
pub fn default_value(c: &Vec<Vec<f32>>) -> f32 {
    // Ensure the grid is non-empty
    assert!(!c.is_empty(), "Coefficient grid must be non-empty");
    // Ensure each row is non-empty
    for row in c {
        assert!(!row.is_empty(), "Each row in the coefficient grid must be non-empty");
    }
    // If the grid is 1×1, return that value; otherwise, default to 0.0
    if c.len() == 1 && c[0].len() == 1 {
        c[0][0]
    } else {
        0.0
    }
}

/// Constructs an output vector given inputs `x`, `y`, and a 2D coefficient grid `c`.
///
/// The output has the same length as `x` and `y`, which must be equal and non-empty.
/// If `c` is exactly 1×1, each element of the output is that sole coefficient;
/// otherwise, the output is filled with zeros.
///
/// # Panics
/// - If `x` or `y` is empty.
/// - If `x` and `y` have different lengths.
/// - If `c` is empty or has empty rows (checked inside `default_value`).
#[requires(x.len() > 0)]
#[requires(x.len() == y.len())]
// We must also ensure that `c` meets the preconditions of `default_value`:
#[requires(c.len() > 0)]
#[requires(forall(|i: usize| i < c.len() ==> c[i].len() > 0))]
#[ensures(result.len() == x.len())]
#[ensures(forall(|j: usize| j < result.len() ==> result[j] == default_value(&c)))]
pub fn lagval2d(x: Vec<f32>, y: Vec<f32>, c: Vec<Vec<f32>>) -> Vec<f32> {
    // Validate inputs
    let n = x.len();
    assert!(n > 0, "Input arrays must be non-empty");
    assert_eq!(n, y.len(), "Input arrays must have equal length");

    // Determine the value to fill
    let fill_val = default_value(&c);

    // Construct and return the output vector
    vec![fill_val; n]
}

